mapper.delete:
DELETE FROM course_country
 WHERE course_id = #{courseId,jdbcType=NUMERIC}
   AND EXISTS (SELECT 1 FROM course c
                WHERE c.course_id = #{courseId,jdbcType=NUMERIC}
                  AND c.creation_type = 'SYSTEM'
                  AND c.deleted_at IS NULL)

mapper.update:
UPDATE course_place
   SET recommendation_reason = #{recommendationReason,jdbcType=VARCHAR}
 WHERE course_id = #{courseId,jdbcType=NUMERIC}
   AND place_id  = #{placeId,jdbcType=NUMERIC}
   AND EXISTS (SELECT 1 FROM course c
                WHERE c.course_id = #{courseId,jdbcType=NUMERIC}
                  AND c.creation_type = 'SYSTEM'
                  AND c.deleted_at IS NULL)

UPDATE post
   SET content = #{content,jdbcType=CLOB}
 WHERE course_id = #{courseId,jdbcType=NUMERIC}
   AND deleted_at IS NULL
   AND EXISTS (SELECT 1 FROM course c
                WHERE c.course_id = #{courseId,jdbcType=NUMERIC}
                  AND c.creation_type = 'SYSTEM'
                  AND c.deleted_at IS NULL)
